/* ChartPulse — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Mono:wght@400;500&display=swap');

:root {
  --bg-base: #0d0d14;
  --bg-card: #13131f;
  --bg-card2: #1a1a2a;
  --bg-hover: #1f1f30;
  --bg-active: #252538;
  --border: #2a2a3d;
  --border-light: #1e1e2e;
  --text-primary: #e8e8f0;
  --text-secondary: #8888a8;
  --text-muted: #55556a;
  --accent-blue: #2962ff;
  --accent-blue-hover: #3d74ff;
  --accent-blue-dim: rgba(41,98,255,0.15);
  --gain: #26a69a;
  --gain-dim: rgba(38,166,154,0.15);
  --loss: #ef5350;
  --loss-dim: rgba(239,83,80,0.15);
  --gold: #f7b731;
  --platinum: #a0a8c0;
  --nav-height: 52px;
  --sidebar-width: 280px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'DM Sans', sans-serif;
  background: var(--bg-base);
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ── Navigation ── */
.nav {
  position: sticky; top: 0; z-index: 100;
  height: var(--nav-height);
  background: rgba(13,13,20,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center;
  padding: 0 20px;
  gap: 0;
}

.nav-logo {
  display: flex; align-items: center; gap: 8px;
  font-size: 16px; font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  margin-right: 24px;
  letter-spacing: -0.3px;
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 28px; height: 28px;
  background: var(--accent-blue);
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
}

.nav-links {
  display: flex; align-items: center; gap: 2px;
  flex: 1;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 13px; font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  transition: color 0.15s, background 0.15s;
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }
.nav-link.active { color: var(--text-primary); background: var(--bg-active); }

.nav-search {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-card2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 10px;
  width: 200px; flex-shrink: 0;
  margin: 0 12px;
  transition: border-color 0.15s;
}

.nav-search:focus-within { border-color: var(--accent-blue); }

.nav-search input {
  background: none; border: none; outline: none;
  color: var(--text-primary); font-size: 12px;
  width: 100%;
  font-family: inherit;
}

.nav-search input::placeholder { color: var(--text-muted); }

.nav-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

.btn {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: inherit; font-size: 12px; font-weight: 600;
  border: none; cursor: pointer; border-radius: 6px;
  padding: 7px 14px;
  text-decoration: none;
  transition: all 0.15s;
  white-space: nowrap;
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
}
.btn-ghost:hover { background: var(--bg-hover); color: var(--text-primary); }

.btn-primary {
  background: var(--accent-blue);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-blue-hover); }

.btn-sm { padding: 5px 10px; font-size: 11px; }

/* ── Ticker Bar ── */
.ticker-bar {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  height: 36px;
  display: flex; align-items: center;
}

.ticker-track {
  display: flex; align-items: center; gap: 0;
  animation: ticker-scroll 40s linear infinite;
  white-space: nowrap;
  width: max-content;
}

.ticker-bar:hover .ticker-track { animation-play-state: paused; }

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.ticker-item {
  display: flex; align-items: center; gap: 6px;
  padding: 0 18px;
  border-right: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.1s;
  height: 36px;
}
.ticker-item:hover { background: var(--bg-hover); }

.ticker-symbol { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.ticker-price { font-size: 12px; color: var(--text-secondary); font-family: 'DM Mono', monospace; }
.ticker-change { font-size: 11px; font-weight: 600; font-family: 'DM Mono', monospace; }

/* ── Badges / Pills ── */
.badge { display: inline-flex; align-items: center; gap: 3px; padding: 2px 7px; border-radius: 4px; font-size: 11px; font-weight: 600; font-family: 'DM Mono', monospace; }
.badge-gain { background: var(--gain-dim); color: var(--gain); }
.badge-loss { background: var(--loss-dim); color: var(--loss); }
.badge-neutral { background: rgba(136,136,168,0.15); color: var(--text-secondary); }
.badge-blue { background: var(--accent-blue-dim); color: var(--accent-blue); }
.badge-gold { background: rgba(247,183,49,0.15); color: var(--gold); }
.badge-plat { background: rgba(160,168,192,0.15); color: var(--platinum); }

.gain { color: var(--gain); }
.loss { color: var(--loss); }

/* ── Cards ── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}

.card-header {
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}

.card-title { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.card-body { padding: 14px 16px; }

/* ── Tables ── */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  font-size: 11px; font-weight: 600; color: var(--text-muted);
  text-align: left; padding: 8px 10px;
  border-bottom: 1px solid var(--border);
  letter-spacing: 0.5px; text-transform: uppercase;
}
.data-table td { padding: 8px 10px; border-bottom: 1px solid var(--border-light); }
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .num { font-family: 'DM Mono', monospace; font-size: 12px; }
.data-table .sym { font-weight: 600; color: var(--text-primary); }

/* ── Tabs ── */
.tabs { display: flex; align-items: center; gap: 2px; }
.tab {
  font-size: 12px; font-weight: 500;
  color: var(--text-secondary);
  padding: 6px 12px; border-radius: 6px;
  cursor: pointer; border: none; background: none;
  font-family: inherit;
  transition: color 0.15s, background 0.15s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-primary); background: var(--bg-hover); }
.tab.active { color: var(--text-primary); background: var(--bg-active); }

.tabs-bar {
  display: flex; align-items: center; gap: 0;
  border-bottom: 1px solid var(--border);
  padding: 0 16px;
  overflow-x: auto;
}
.tabs-bar::-webkit-scrollbar { height: 0; }
.tab-bar-item {
  font-size: 12px; font-weight: 500;
  color: var(--text-secondary);
  padding: 10px 14px; cursor: pointer;
  border: none; background: none; font-family: inherit;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.tab-bar-item:hover { color: var(--text-primary); }
.tab-bar-item.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }

/* ── Sparkline ── */
.sparkline { display: inline-block; vertical-align: middle; }

/* ── Misc ── */
.section { padding: 24px 20px; }
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.section-title { font-size: 15px; font-weight: 700; }
.section-subtitle { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }

.divider { height: 1px; background: var(--border); margin: 0; }

.tag { display: inline-flex; align-items: center; padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 500; border: 1px solid var(--border); color: var(--text-secondary); }
.tag-active { border-color: var(--accent-blue); color: var(--accent-blue); background: var(--accent-blue-dim); }

.avatar { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; flex-shrink: 0; }

/* ── Footer ── */
.footer { background: var(--bg-card); border-top: 1px solid var(--border); padding: 40px 20px 24px; margin-top: 40px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 24px; max-width: 1400px; margin: 0 auto; }
.footer-col-title { font-size: 11px; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 12px; }
.footer-link { display: block; color: var(--text-secondary); text-decoration: none; font-size: 12px; padding: 3px 0; transition: color 0.15s; }
.footer-link:hover { color: var(--text-primary); }
.footer-bottom { max-width: 1400px; margin: 28px auto 0; padding-top: 20px; border-top: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; }
.footer-copy { font-size: 11px; color: var(--text-muted); }

/* ── Responsive ── */
@media (max-width: 1200px) {
  :root { --sidebar-width: 240px; }
}
@media (max-width: 768px) {
  .nav-search { display: none; }
  .nav-links .nav-link { padding: 6px 8px; font-size: 12px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .nav-links { gap: 0; }
  .nav-links .nav-link { padding: 6px 6px; font-size: 11px; }
}

