  candles.style.opacity = '0.5';
  setTimeout(() => { candles.style.transition = 'opacity 0.3s'; candles.style.opacity = '1'; }, 100);
}

function setFinTab(id, btn) {
  document.querySelectorAll('#fin-annual, #fin-quarterly').forEach(el => el.classList.remove('active'));
  btn.closest('.detail-section').querySelectorAll('.tab').forEach(b => b.classList.remove('active'));
  document.getElementById('fin-' + id).classList.add('active');
  btn.classList.add('active');
}

function selectSymbol(row, sym, name, price, chg, chgPct, dir) {
  document.querySelectorAll('.watchlist-row').forEach(r => r.classList.remove('active'));
  row.classList.add('active');
  // Update symbol bar
  document.querySelector('.symbol-name').textContent = sym;
  document.querySelector('.detail-ticker').textContent = sym + ' · NASDAQ';
  document.querySelector('.detail-name').textContent = name;
  document.querySelector('.detail-price').textContent = price;
  const cv = document.querySelector('.detail-change-val');
  cv.textContent = chg + ' (' + chgPct + ')';
  cv.className = 'detail-change-val ' + dir;
}
</script>
</body>
